def fractional_knapsack(capacity, items):
    # 按单位价值（价值/重量）降序排序
    items = sorted(items, key=lambda x: x[1] / x[0], reverse=True)
    total_value = 0.0
    for weight, value in items:
        if capacity <= 0:
            break
        if weight <= capacity:
            capacity -= weight
            total_value += value
        else:
            fraction = capacity / weight
            total_value += value * fraction
            capacity = 0
    return total_value

# 示例测试
if __name__ == "__main__":
    print(fractional_knapsack(50, [(10,60), (20,100), (30,120)]))  # 输出 240.0
